@staticmethod
def temperature_schedule_set(data: Dict[str, Any], endpoints: List[str], schedule: Dict[str, Any]) -> str:
    """
    Set a temperature schedule for one or more thermostat devices.

    Args:
        data: The data dictionary containing devices
        endpoints: List of device endpoint IDs to adjust
        schedule: Dictionary containing temperature schedule information
            {
                "weekday": [
                    {"time": "06:00", "temperature": 22},
                    {"time": "08:30", "temperature": 18},
                    {"time": "17:00", "temperature": 22},
                    {"time": "22:00", "temperature": 16}
                ],
                "weekend": [
                    {"time": "08:00", "temperature": 22},
                    {"time": "23:00", "temperature": 16}
                ]
            }

    Returns:
        A JSON string with the result of the operation
    """
    if not endpoints:
        return json.dumps({
            "success": False,
            "message": "No devices specified"
        })

    if not schedule:
        return json.dumps({
            "success": False,
            "message": "No schedule specified"
        })

    # Validate schedule format
    if not validate_schedule_format(schedule):
        return json.dumps({
            "success": False,
            "message": "Invalid schedule format"
        })

    # Get the current user's home ID
    home_id = get_user_home_id(data)

    results = []
    for endpoint in endpoints:
        device = find_device_by_endpoint(data, endpoint, home_id)
        if device and "temperature_schedule_set" in device["supported_apis"]:
            # Update the device schedule in the data dictionary
            for i, d in enumerate(data["devices"]):
                if d["endpoint"] == endpoint and (home_id is None or d["home_id"] == home_id):
                    if "schedules" not in data["devices"][i]:
                        data["devices"][i]["schedules"] = {}
                    data["devices"][i]["schedules"]["temperature"] = schedule
                    success = True
                    break
            else:
                success = False

            if success:
                results.append({
                    "endpoint": endpoint,
                    "name": device["name"],
                    "success": True,
                    "message": f"Set temperature schedule for {device['name']}",
                    "schedule": schedule
                })
            else:
                results.append({
                    "endpoint": endpoint,
                    "success": False,
                    "message": f"Failed to update schedule for device with endpoint {endpoint}"
                })
        else:
            results.append({
                "endpoint": endpoint,
                "success": False,
                "message": f"Device with endpoint {endpoint} not found or does not support temperature scheduling"
            })

    return json.dumps({
        "success": any(result["success"] for result in results),
        "results": results
    })
```

